import { useState } from 'react';
import { BaseNode, FieldText, FieldSelect } from './BaseNode';
import { LogOut } from 'lucide-react';

export const OutputNode = ({ id, data }) => {
  const [currName,   setCurrName]   = useState(data?.outputName || id.replace('customOutput-', 'output_'));
  const [outputType, setOutputType] = useState(data?.outputType || 'Text');

  return (
    <BaseNode id={id} title="Output" accentColor="#ec4899" Icon={LogOut}
      inputs={[{ id: 'value', label: 'value' }]}>
      <FieldText   label="Name" value={currName}   onChange={e => setCurrName(e.target.value)}   placeholder="output_name" />
      <FieldSelect label="Type" value={outputType} onChange={e => setOutputType(e.target.value)}
        options={[{ value: 'Text', label: 'Text' }, { value: 'Image', label: 'Image' }]} />
    </BaseNode>
  );
};
